import {winText} from './grab-report.js';
export function renderGrabEqual(study,{esc,table}){
 let html=`<section class="panel"><h2>Equal grab attack · balance comparison</h2><p>${study.runs.reduce((s,r)=>s+r.bouts,0)} bouts; ${(study.totalRuntimeSeconds/60).toFixed(1)} summed tournament minutes. Default gameplay unchanged.</p>${study.findings.map(n=>`<p>${esc(n)}</p>`).join('')}<details><summary>Method, equal-rate test and remaining limits</summary>${study.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</details></section>`;
 for(const delay of [10,15]){const rows=study.runs.filter(r=>r.config.delay===delay),keys=Object.keys(rows[0].outcomes).sort((a,b)=>Number(b.startsWith('defence-capable'))-Number(a.startsWith('defence-capable')));
 html+=`<section class="panel"><h2>${delay}f · ten modes side by side</h2>${table(['Group / opponent',...rows.map(r=>r.config.mode)],keys.map(k=>[k.replace(/^skilled\//,'original three/'),...rows.map(r=>winText(r.outcomes[k]))]))}<h3>Capture damage both ways · timer + reader + punisher</h3>${table(['Mode','Opponent','Bots capture HP / total','Bots capture share','Masher capture HP / total','Masher capture share'],rows.flatMap(r=>Object.entries(r.twoWay).map(([k,v])=>[r.config.mode,k,`${v.botCaptureDamage.toFixed(1)} / ${v.botDamage.toFixed(1)}`,`${(100*v.botCaptureDamage/v.botDamage).toFixed(1)}%`,`${v.masherCaptureDamage.toFixed(1)} / ${v.masherDamage.toFixed(1)}`,`${(100*v.masherCaptureDamage/v.masherDamage).toFixed(1)}%`])))}<h3>Offensive grab validity</h3>${table(['Mode','Bot / opponent','Bouts','Lottery attempts / eligible frames','Lottery rate; descriptive 95%','Dedicated capture presses','Captures started / landed','Capture HP / all HP','Capture share'],rows.flatMap(r=>Object.entries(r.offense).map(([k,v])=>[r.config.mode,k,v.bouts,`${v.grabAttackAttempts} / ${v.grabAttackEligibleFrames}`,v.attackRate==null?'not applicable':`${(100*v.attackRate).toFixed(3)}%; ${v.attackRateInterval.map(x=>(100*x).toFixed(3)).join('–')}%`,v.capturePresses,`${v.capturesStarted} / ${v.capturesLanded}`,`${v.captureDamage.toFixed(1)} / ${v.damage.toFixed(1)}`,`${(100*v.captureShare).toFixed(1)}%`])))}<h3>Break validity</h3>${table(['Mode','Bot','Faced / close','Reaction / guess attempts','Reaction / guess successes','All breaks','Wasted / pending'],rows.flatMap(r=>Object.entries(r.breaks).map(([k,v])=>[r.config.mode,k,`${v.capturesFaced} / ${v.closeCapturesFaced}`,`${v.reactionBreakAttempts} / ${v.guessBreakAttempts}`,`${v.reactionBreaksLanded} / ${v.guessBreaksLanded}`,v.breaksLanded,`${v.wastedBreakTaps} / ${v.pendingBreakTaps}`])))}<h3>Sanity vs random</h3>${table(['Mode','Bot','Wins; 95% range','Screen'],rows.flatMap(r=>Object.entries(r.sanity).map(([k,v])=>[r.config.mode,k,winText(v),v.interval[0]>.5?'passes':'UNTRUSTED'])))}<details><summary>All comparisons and luck ranges</summary>${table(['Group / opponent','A','B','Difference','Interpretation'],study.comparisons.filter(c=>c.delay===delay).map(c=>[c.key,c.a,c.b,c.difference.toFixed(1)+' pp',c.label]))}</details></section>`;
 }
 return html;
}
